/** Rows written per insert, to stay under SQLite's bound-parameter limit. */
const MERGE_INSERT_BATCH_SIZE = 500;

/**
 * Moves every issue from `sourceLabelId` onto `targetLabelId`, then deletes the
 * source label — all in one transaction. Issues that already carry the target
 * keep their single join row. Returns how many issues carried the source.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const issueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    for (let start = 0; start < issueIds.length; start += MERGE_INSERT_BATCH_SIZE) {
      const batch = issueIds.slice(start, start + MERGE_INSERT_BATCH_SIZE);
      tx.insert(issueLabels)
        .values(
          batch.map((issueId) => ({ orgId, issueId, labelId: targetLabelId })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(
        and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)),
      )
      .run();

    return issueIds.length;
  });
}

/** Replaces the whole label set of one issue in a single round trip. */

